#!/usr/bin/env node
/**
 * bulk-fill-placeholder-answers.js
 *
 * Finds every placeholder-style answer in final-qa-dataset.json (and mirrors
 * to public/qa-dataset.json) and replaces them with genuine, production-ready
 * answers generated by a local Ollama model.
 *
 * Usage:
 *   node scripts/bulk-fill-placeholder-answers.js            # dry-run (no write)
 *   node scripts/bulk-fill-placeholder-answers.js --apply    # write results
 *   node scripts/bulk-fill-placeholder-answers.js --apply --force   # re-generate all placeholders even if cached
 *   ANSWER_CONCURRENCY=4 node scripts/bulk-fill-placeholder-answers.js --apply
 *
 * The script caches generated answers in scripts/answer-bank/bulk-generated-cache.json
 * so it can be safely interrupted and resumed.
 */

const fs   = require("fs");
const path = require("path");
require("dotenv").config({ path: path.join(__dirname, "..", ".env"), quiet: true });

// ── paths ─────────────────────────────────────────────────────────────────────
const ROOT              = path.join(__dirname, "..");
const FINAL_PATH        = path.join(__dirname, "answer-bank", "final-qa-dataset.json");
const PUBLIC_PATH       = path.join(ROOT, "public", "qa-dataset.json");
const CACHE_PATH        = path.join(__dirname, "answer-bank", "bulk-generated-cache.json");
// Pre-existing answer maps generated by earlier scripts
const OLLAMA_PREV_PATH  = path.join(__dirname, "answer-bank", "actual-interview-ollama-updated-answers.json");
const GENERATED_PREV_PATH = path.join(__dirname, "answer-bank", "actual-interview-generated-answers.json");

// ── config ────────────────────────────────────────────────────────────────────
const PROVIDER    = process.env.ANSWER_PROVIDER || process.env.LLM_PROVIDER || "ollama";
const MODEL       = PROVIDER === "openai"
  ? (process.env.OPENAI_MODEL || "gpt-5-mini")
  : (process.env.OLLAMA_MODEL || "llama3.1:8b");
const ENDPOINT    = process.env.OLLAMA_URL     || "http://127.0.0.1:11434/api/generate";
const OPENAI_API_KEY = process.env.OPENAI_API_KEY || "";
const CONCURRENCY = Math.max(1, Number(process.env.ANSWER_CONCURRENCY || 1)); // 1 is optimal for single GPU
const APPLY       = process.argv.includes("--apply");
const FORCE       = process.argv.includes("--force");

// Optional: only process a slice for testing, e.g. --sample=20
const sampleArg   = process.argv.find(a => a.startsWith("--sample="));
const SAMPLE      = sampleArg ? Number(sampleArg.split("=")[1]) : 0;

// ── placeholder detection (mirrors audit-answer-quality.js) ───────────────────
const PLACEHOLDER_PATTERNS = [
  /a strong answer should/i,
  /use a truthful star answer/i,
  /for this scenario,? first confirm user impact/i,
  /the practical answer is to state what changes/i,
  /in an interview,? (i would|also) mention/i,
  /so the answer sounds production-ready instead of theoretical/i,
  /tailor (the|your) (response|answer)/i,
  /answer (this|the question) (by|with)/i,
  /you should (say|state|mention|explain|describe)/i,
  /tailor the response directly to/i,
  /use the prompt details as acceptance criteria/i,
  /start with the expected configuration, command, workflow/i,
  /the direct answer is to define/i,
  /i would explain the main mechanism/i,
];

function isPlaceholder(answer) {
  const v = String(answer || "").trim();
  if (!v || v.length < 80) return true;
  return PLACEHOLDER_PATTERNS.some(p => p.test(v));
}

// ── cache key: stable normalised question text ─────────────────────────────────
function cacheKey(question) {
  return String(question || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

// ── Ollama prompt ──────────────────────────────────────────────────────────────
function buildPrompt(entry) {
  const topic = [entry.topic, entry.category].filter(Boolean).join("/");
  return `You are writing a technically accurate reference answer for a senior ${topic || "DevOps/Cloud"} interview question.

Requirements:
- Answer the exact question directly in 80-140 words.
- Use only real commands, flags, APIs, and product behavior. Never invent a flag, UI, metric, or mechanism.
- Include concrete verification or operational detail when relevant.
- Do not repeat the question, add a preamble, give coaching instructions, or discuss how to answer.
- Do not use placeholders unless the question explicitly asks for personal experience; for those questions use [CONTEXT], [ACTION], and [RESULT] instead of invented claims.
- End with a complete sentence. Silently fact-check the answer before returning it.

Q: ${entry.question}
A:`;
}

// ── quality gate on generated answer ──────────────────────────────────────────
function isInvalidGenerated(text) {
  const v = String(text || "").trim();
  const words = v.split(/\s+/).filter(Boolean);
  if (!v || words.length < 55 || words.length > 190) return true;
  if (!/[.!?)]$/.test(v)) return true;
  if (PLACEHOLDER_PATTERNS.some(p => p.test(v))) return true;
  if (/\b(i am an expert|i am a senior|i am experienced)\b/i.test(v)) return true;
  if (/\[(?:PROJECT|METRIC|TOOL|TIMELINE)\]/i.test(v)) return true;
  if (/\b(?:Helm UI|--keep-empty|--validate-values|--template-dir)\b/i.test(v)) return true;
  return false;
}

// ── Ollama call (streaming via Node http module — fetch hangs on macOS) ─────────
const http = require("http");
const url  = require("url");

function generateOllamaAnswer(entry) {
  return new Promise((resolve, reject) => {
    const prompt  = buildPrompt(entry);
    const payload = JSON.stringify({
      model  : MODEL,
      prompt,
      stream : true,
      options: { temperature: 0, num_ctx: 4096, num_predict: 240 },
    });
    const parsed = url.parse(ENDPOINT);
    const reqOpts = {
      hostname: parsed.hostname,
      port    : Number(parsed.port) || 11434,
      path    : parsed.path,
      method  : "POST",
      headers : {
        "content-type"  : "application/json",
        "content-length": Buffer.byteLength(payload),
      },
    };

    const req = http.request(reqOpts, (res) => {
      let answer = "";
      let buf    = "";
      res.on("data", (chunk) => {
        buf += chunk.toString();
        const lines = buf.split("\n");
        buf = lines.pop();
        for (const line of lines) {
          if (!line.trim()) continue;
          try {
            const c = JSON.parse(line);
            answer += c.response || "";
          } catch { /* skip malformed */ }
        }
      });
      res.on("end", () => {
        const cleaned = answer.trim()
          .replace(/^```(?:\w+)?\s*/, "")
          .replace(/```$/, "")
          .trim();
        if (!cleaned) return reject(new Error("Empty response from Ollama"));
        if (isInvalidGenerated(cleaned)) return reject(new Error(`Quality check failed: ${cleaned.slice(0, 100).replace(/\n/g, " ")}`));
        resolve(cleaned);
      });
      res.on("error", reject);
    });

    req.on("error", reject);
    req.setTimeout(90000, () => { req.destroy(); reject(new Error("Ollama request timed out")); });
    req.write(payload);
    req.end();
  });
}

function openAIOutputText(response) {
  if (typeof response.output_text === "string") return response.output_text.trim();
  return (Array.isArray(response.output) ? response.output : [])
    .flatMap((item) => Array.isArray(item.content) ? item.content : [])
    .filter((item) => item.type === "output_text" && typeof item.text === "string")
    .map((item) => item.text)
    .join("\n")
    .trim();
}

let openAIRateLimitUntil = 0;

function retryDelayMs(response, message) {
  const retryAfter = Number(response.headers.get("retry-after"));
  if (Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const match = String(message).match(/try again in\s*(?:(\d+)m)?\s*(?:(\d+(?:\.\d+)?)s)?/i);
  if (!match) return 60000;
  return ((Number(match[1] || 0) * 60) + Number(match[2] || 0)) * 1000;
}

async function waitForOpenAIRateLimit() {
  const waitMs = openAIRateLimitUntil - Date.now();
  if (waitMs > 0) await new Promise((resolve) => setTimeout(resolve, waitMs));
}

async function generateOpenAIAnswer(entry) {
  if (!OPENAI_API_KEY) throw new Error("OPENAI_API_KEY is not set");
  for (let attempt = 1; attempt <= 8; attempt++) {
    await waitForOpenAIRateLimit();
    const response = await fetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: { "content-type": "application/json", authorization: `Bearer ${OPENAI_API_KEY}` },
      body: JSON.stringify({
        model: MODEL,
        input: buildPrompt(entry),
        max_output_tokens: 1000,
        reasoning: { effort: "low" }
      })
    });
    if (response.ok) {
      const answer = openAIOutputText(await response.json());
      if (isInvalidGenerated(answer)) throw new Error(`Quality check failed: ${answer.slice(0, 100).replace(/\n/g, " ")}`);
      return answer;
    }
    const message = await response.text();
    if (response.status !== 429 || attempt === 8) throw new Error(`OpenAI ${response.status}: ${message.slice(0, 300)}`);
    const delay = retryDelayMs(response, message) + 2000;
    openAIRateLimitUntil = Math.max(openAIRateLimitUntil, Date.now() + delay);
    console.warn(`\nOpenAI rate limit reached; pausing for ${Math.ceil(delay / 1000)}s, then retrying.`);
  }
  throw new Error("OpenAI retry limit reached");
}

function generateAnswer(entry) {
  return PROVIDER === "openai" ? generateOpenAIAnswer(entry) : generateOllamaAnswer(entry);
}

// ── progress bar (simple) ──────────────────────────────────────────────────────
let lastLoggedPct = -1;
function progress(done, total, errors, logPath) {
  const pct  = Math.round((done / total) * 100);
  const bar  = "█".repeat(Math.floor(pct / 5)) + "░".repeat(20 - Math.floor(pct / 5));
  process.stdout.write(`\r[${bar}] ${pct}%  ${done}/${total}  errors=${errors}   `);
  // Log every 1% so we can tail the file
  if (Math.floor(pct) > lastLoggedPct && Math.floor(pct) % 1 === 0 && logPath) {
    lastLoggedPct = Math.floor(pct);
    const ts = new Date().toISOString();
    fs.appendFileSync(logPath, `\n[${ts}] ${pct}%  ${done}/${total}  errors=${errors}`);
  }
}

// ── main ───────────────────────────────────────────────────────────────────────
async function run() {
  // ── load dataset ─────────────────────────────────────────────────────────────
  if (!fs.existsSync(FINAL_PATH)) {
    console.error(`Dataset not found: ${FINAL_PATH}`);
    process.exit(1);
  }
  const dataset = JSON.parse(fs.readFileSync(FINAL_PATH, "utf8"));
  console.log(`Loaded ${dataset.length} entries from final-qa-dataset.json`);

  // ── identify placeholders ──────────────────────────────────────────────────────
  const needsUpdate = dataset
    .map((entry, idx) => ({ entry, idx }))
    .filter(({ entry }) => isPlaceholder(entry.answer));

  const selected = SAMPLE > 0 ? needsUpdate.slice(0, SAMPLE) : needsUpdate;
  console.log(`Found ${needsUpdate.length} placeholder answers. Processing ${selected.length}${SAMPLE ? ` (sample)` : ""}.`);
  if (!APPLY) console.log("DRY RUN — pass --apply to write changes.\n");

  // ── load cache (merge pre-existing answer maps in on first run) ───────────────
  const cache = fs.existsSync(CACHE_PATH)
    ? JSON.parse(fs.readFileSync(CACHE_PATH, "utf8"))
    : {};

  // Seed cache from earlier ollama/generated answer map files if not already present
  let seeded = 0;
  for (const srcPath of [OLLAMA_PREV_PATH, GENERATED_PREV_PATH]) {
    if (!fs.existsSync(srcPath)) continue;
    const map = JSON.parse(fs.readFileSync(srcPath, "utf8"));
    for (const [k, v] of Object.entries(map)) {
      const nk = cacheKey(k);
      if (!nk) continue;
      const val = String(v || "").trim();
      if (!isInvalidGenerated(val) && !cache[nk]) {
        cache[nk] = val;
        seeded++;
      }
    }
  }
  if (seeded > 0) {
    console.log(`Seeded ${seeded} answers from pre-existing answer maps.`);
    if (APPLY) fs.writeFileSync(CACHE_PATH, JSON.stringify(cache, null, 2) + "\n");
  }

  let cacheHits = 0;
  for (const { entry } of selected) {
    const cached = cache[cacheKey(entry.question)];
    if (cached && !isInvalidGenerated(cached) && !FORCE) cacheHits++;
  }
  console.log(`Cache hits (will skip): ${cacheHits}  |  Need ${PROVIDER === "openai" ? "OpenAI" : "Ollama"}: ${selected.length - cacheHits}`);
  console.log(`Provider: ${PROVIDER}  |  Model: ${MODEL}  |  Concurrency: ${CONCURRENCY}\n`);

  // ── worker pool ────────────────────────────────────────────────────────────────
  const LOG_PATH = path.join(ROOT, "logs", `bulk-fill-progress-${Date.now()}.log`);
  fs.writeFileSync(LOG_PATH, `[${new Date().toISOString()}] Starting: ${selected.length} questions, ${cacheHits} cache hits\n`);
  let done = 0;
  let errors = 0;
  let queueIdx = 0;
  const generatedThisRun = new Set();

  async function worker() {
    while (queueIdx < selected.length) {
      const { entry, idx } = selected[queueIdx++];
      const key = cacheKey(entry.question);

      if (cache[key] && !isInvalidGenerated(cache[key]) && !FORCE) {
        done++;
        progress(done, selected.length, errors, LOG_PATH);
        continue;
      }

      try {
        const answer = await generateAnswer(entry);
        cache[key] = answer;
        generatedThisRun.add(key);
        // persist cache after every answer so we can resume on crash
        if (APPLY) {
          fs.writeFileSync(CACHE_PATH, JSON.stringify(cache, null, 2) + "\n");
        }
      } catch (err) {
        errors++;
        console.error(`\n  ✗ [${idx}] ${entry.question.slice(0, 80)}: ${err.message}`);
        fs.appendFileSync(LOG_PATH, `\n  ✗ [${idx}] ${entry.question.slice(0, 80)}: ${err.message}`);
      }

      done++;
      progress(done, selected.length, errors, LOG_PATH);
    }
  }

  const workers = Array.from({ length: Math.min(CONCURRENCY, selected.length || 1) }, () => worker());
  await Promise.all(workers);
  console.log(`\n\nGeneration complete. Errors: ${errors}`);

  // ── apply to dataset ───────────────────────────────────────────────────────────
  if (APPLY) {
    let updated = 0;
    for (const { entry, idx } of selected) {
      const key = cacheKey(entry.question);
      if (cache[key] && !isInvalidGenerated(cache[key]) && (!FORCE || generatedThisRun.has(key))) {
        dataset[idx] = { ...entry, answer: cache[key] };
        updated++;
      }
    }

    // write final-qa-dataset.json
    fs.writeFileSync(FINAL_PATH, JSON.stringify(dataset, null, 2) + "\n");
    console.log(`Updated final-qa-dataset.json — ${updated} answers replaced.`);

    // mirror to public/qa-dataset.json
    if (fs.existsSync(PUBLIC_PATH)) {
      fs.writeFileSync(PUBLIC_PATH, JSON.stringify(dataset, null, 2) + "\n");
      console.log(`Mirrored to public/qa-dataset.json`);
    }

    // save final cache snapshot
    fs.writeFileSync(CACHE_PATH, JSON.stringify(cache, null, 2) + "\n");
    console.log(`Cache saved to ${CACHE_PATH}`);
  } else {
    console.log("Dry run — no files written. Re-run with --apply to save.");
  }

  if (errors > 0) {
    console.warn(`\nWarning: ${errors} questions could not be answered. Re-run to retry them.`);
    process.exitCode = 1;
  }
}

run().catch(err => {
  console.error("\nFatal:", err.stack || err.message);
  process.exit(1);
});
